const ids = ["6:7","6:23","48:43","48:54","5:17","5:22","5:27","5:37","5:42","5:47","5:55","5:60","5:65","5:70","5:78","5:83"];
const out = [];
function dump(n, depth){
  const o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if(n.type==="TEXT"){o.chars=n.characters; o.font=n.fontName; o.size=n.fontSize;}
  if("fills" in n && Array.isArray(n.fills)){
    o.fills = n.fills.map(f=>{
      if(f.type==="IMAGE") return {type:"IMAGE", hash:f.imageHash, scaleMode:f.scaleMode};
      if(f.type==="SOLID") return {type:"SOLID", color:f.color, opacity:f.opacity};
      return {type:f.type};
    });
  }
  if("strokes" in n && n.strokes && n.strokes.length) o.strokes = n.strokes.map(s=>({type:s.type,color:s.color}));
  if("cornerRadius" in n) o.radius = n.cornerRadius;
  if("children" in n && depth>0){ o.children = n.children.map(c=>dump(c, depth-1)); }
  return o;
}
for(const id of ids){
  const n = await figma.getNodeByIdAsync(id);
  if(n) out.push(dump(n, 4));
  else out.push({id, missing:true});
}
// also list all components in file
const comps = figma.root.findAll(n=>n.type==="COMPONENT"||n.type==="COMPONENT_SET").map(c=>({id:c.id,name:c.name,type:c.type}));
return JSON.stringify({out, comps}, null, 1);

