  if("fills" in n && Array.isArray(n.fills) && n.fills.length) o.fills=n.fills.map(f=>f.type==="SOLID"?{t:"S",c:f.color}:{t:f.type});
  if("strokes" in n && n.strokes && n.strokes.length) o.strokes=n.strokes.map(s=>({c:s.color,w:n.strokeWeight}));
  if("children" in n && depth>0) o.ch=n.children.map(c=>dump(c,depth-1));
  return o;
}
