async function T(chars,{fam="Inter",st="Regular",size=14,color=C.ink,lh,align,width,ls,name}={}){
  const t=figma.createText(); t.fontName={family:fam,style:st}; t.fontSize=size; t.characters=chars;
  t.fills=[{type:"SOLID",color}]; if(lh)t.lineHeight={value:lh,unit:"PIXELS"};
  if(align)t.textAlignHorizontal=align; if(width){t.textAutoResize="HEIGHT";t.resize(width,t.height);} if(ls)t.letterSpacing={value:ls,unit:"PIXELS"}; if(name)t.name=name;
  return t;
}
