  const hdr=figma.createFrame(); hdr.name="Header"; hdr.resize(414,56); hdr.fills=[]; hdr.layoutMode="HORIZONTAL"; hdr.counterAxisAlignItems="CENTER"; hdr.primaryAxisSizingMode="FIXED"; hdr.counterAxisSizingMode="FIXED"; hdr.paddingLeft=20; hdr.paddingRight=20;
