  const sp2=figma.createFrame(); sp2.resize(10,32); sp2.fills=[]; body.appendChild(sp2);
  // Full name
  const form=auto("VERTICAL",18); form.layoutAlign="STRETCH";
  async function labeled(lbl,node,err){
    const w=auto("VERTICAL",7); w.layoutAlign="STRETCH";
    w.appendChild(await T(lbl,{fam:"Inter",st:"Semi Bold",size:13,color:C.body,name:"Lbl_"+lbl}));
