  if(mode==="error"){
    const ef=await field("jonas.macroni@invest",{state:"error"});
    form.appendChild(await labeled("Email address", ef, "Enter a valid email address"));
  } else {
    form.appendChild(await labeled("Email address", await field(mode==="empty"?"Email address":"jonas.macroni@invest.ai",{state:nameState})));
  }
  // password with show/hide toggle
  const pwWrap=figma.createFrame(); pwWrap.name="PasswordWrap"; pwWrap.resize(354,60); pwWrap.fills=[]; pwWrap.clipsContent=false;
  const pf=await field(mode==="empty"?"Password":"••••••••••",{state:nameState}); pwWrap.appendChild(pf); pf.x=0; pf.y=0;
  const tog=await T(mode==="filled"?"Hide":"Show",{fam:"Inter",st:"Semi Bold",size:13,color:C.primary,name:"Btn_TogglePassword"});
  pwWrap.appendChild(tog); tog.x=306; tog.y=20;
  form.appendChild(await labeled("Password", pwWrap));
