const prim={r:0.192,g:0.627,b:0.384};
async function selectTab(tbInst,tabName){
  const tab=tbInst.findOne(n=>n.name===tabName);
  if(!tab)return "no tab "+tabName;
  const ind=tab.findOne(n=>n.name==="Indicator");
  if(ind)ind.visible=true;
  const lbl=tab.findOne(n=>n.name==="Label");
  if(lbl){lbl.fills=[{type:"SOLID",color:prim}];lbl.fontName={family:"Inter",style:"Semi Bold"};}
  const icon=tab.findOne(n=>n.name==="Icon");
  if(icon){
    const vecs=icon.findAll(n=>n.type==="VECTOR");
    for(const v of vecs){try{v.fills=[{type:"SOLID",color:prim}];}catch(e){}}
    const strokes=icon.findAll(n=>n.type==="VECTOR"&&n.strokes&&n.strokes.length);
    for(const v of strokes){try{v.strokes=[{type:"SOLID",color:prim}];}catch(e){}}
  }
  return "ok";
}
