  const tab=tbInst.findOne(n=>n.name===tabName);
  if(!tab)return "no tab";
  const ind=tab.findOne(n=>n.name==="Indicator");
  if(ind)ind.visible=true;
  const lbl=tab.findOne(n=>n.name==="Label");
  if(lbl){lbl.fills=[{type:"SOLID",color:prim}];lbl.fontName={family:"Inter",style:"Semi Bold"};}
  const icon=tab.findOne(n=>n.name==="Icon");
  if(icon){
    const vecs=icon.findAll(n=>n.type==="VECTOR");
    for(const v of vecs){try{v.fills=[{type:"SOLID",color:prim}];}catch(e){}try{if(v.strokes&&v.strokes.length)v.strokes=[{type:"SOLID",color:prim}];}catch(e){}}
  }
  return "ok";
}
