try{
const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
await figma.setCurrentPageAsync(page);
const F={};
for(const nm of ["01_Splash","02_Welcome","03_Create_Account_Empty","03_Create_Account_Filled","03_Create_Account_Error","04_Home","05_My_Asset_Overlay","06_Notification","07_Profile","08_Contact_Info","09_Bank_Account_Info"]){
  F[nm]=page.findOne(n=>n.name===nm);
}
const NAV={type:"NAVIGATE",destinationId:null};
function link(node,dest,anim){
  node.reactions=[{trigger:{type:"ON_CLICK"},actions:[{type:"NAVIGATE",destinationId:dest.id,navigationType:"PUSH",transition:anim||{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}}}]}];
}
// 01 auto-advance
F["01_Splash"].reactions=[{trigger:{type:"AFTER_DELAY",timeout:1500},actions:[{type:"NAVIGATE",destinationId:F["02_Welcome"].id,navigationType:"PUSH",transition:{type:"DISSOLVE",duration:0.4,easing:{type:"EASE_IN_AND_OUT"}}}]}];
// 02 Create account
link(F["02_Welcome"].findOne(n=>n.name==="Btn_CreateAccount"),F["03_Create_Account_Empty"]);
// 03 backs
for(const s of ["Empty","Filled","Error"]){
  const f=F["03_Create_Account_"+s];
  const back=f.findOne(n=>n.name==="Back");
  if(back)link(back,F["02_Welcome"],{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}});
}
// 03 Filled submit
link(F["03_Create_Account_Filled"].findOne(n=>n.name==="Btn_CreateAccount"),F["04_Home"]);
// 04 Home links
const home=F["04_Home"];
const portfolio=home.findOne(n=>n.name==="PortfolioCard")||home.findOne(n=>n.name==="Portfolio");
if(portfolio)link(portfolio,F["05_My_Asset_Overlay"],{type:"SMART_ANIMATE",duration:0.35,easing:{type:"EASE_IN_AND_OUT"}});
const notif=home.findOne(n=>n.name==="Btn_Notif")||home.findOne(n=>n.name==="NotifBtn");
if(notif)link(notif,F["06_Notification"]);
const homeTabBar=home.findOne(n=>n.name==="TabBar");
if(homeTabBar){const acc=homeTabBar.findOne(n=>n.name==="Tab_Account");if(acc)link(acc,F["07_Profile"]);}
// 05 close
const closeBtn=F["05_My_Asset_Overlay"].findOne(n=>n.name==="Btn_Close")||F["05_My_Asset_Overlay"].findOne(n=>n.name==="Close");
if(closeBtn)link(closeBtn,F["04_Home"],{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}});
// 06 back
const b06=F["06_Notification"].findOne(n=>n.name==="Back");
if(b06)link(b06,F["04_Home"]);
// 07 entries
const prof=F["07_Profile"];
const entries=prof.findAll(n=>n.name==="ProfileEntry");
for(const e of entries){
  const t=e.findOne(n=>n.name==="Title");
  if(!t)continue;
  if(t.characters==="Contact Info")link(e,F["08_Contact_Info"]);
  else if(t.characters==="Bank Account Info")link(e,F["09_Bank_Account_Info"]);
}
const profTabBar=prof.findOne(n=>n.name==="TabBar");
if(profTabBar){const ht=profTabBar.findOne(n=>n.name==="Tab_Home");if(ht)link(ht,F["04_Home"]);}
// 08/09 back
const b08=F["08_Contact_Info"].findOne(n=>n.name==="Back");
if(b08)link(b08,F["07_Profile"]);
const b09=F["09_Bank_Account_Info"].findOne(n=>n.name==="Back");
if(b09)link(b09,F["07_Profile"]);
return JSON.stringify({portfolio:!!portfolio,notif:!!notif,close:!!closeBtn,b06:!!b06,b08:!!b08,b09:!!b09,entries:entries.length});
}catch(e){return "ERR: "+e.message+" "+e.stack;}

