const frames=page.children.filter(c=>c.type==="FRAME"&&/^\d\d_/.test(c.name));
const byId={};frames.forEach(f=>byId[f.id]=f.name);
const out=[];
for(const f of frames){
  const nodes=f.findAll(n=>n.reactions&&n.reactions.length>0);
  for(const n of nodes){
    for(const r of n.reactions){
      const act=r.actions[0];
      out.push({from:f.name,node:n.name,trigger:r.trigger.type,dest:act.destinationId?byId[act.destinationId]||act.destinationId:null,nav:act.navigation});
