const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
await figma.setCurrentPageAsync(page);
const frames=page.children.filter(c=>c.type==="FRAME"&&/^\d\d_/.test(c.name));
const byId={};frames.forEach(f=>byId[f.id]=f.name);
const out=frames.map(f=>{
  const rx=[];
  for(const n of f.findAll(x=>x.reactions&&x.reactions.length)){
    for(const r of n.reactions){const a=r.actions[0];rx.push(n.name+"→"+(byId[a.destinationId]||"?")+"("+r.trigger.type+")");}
  }
  return {name:f.name,w:f.width,h:f.height,links:rx};
});
return JSON.stringify(out,null,1);

