function texts(n,acc){if(n.type==="TEXT"&&n.visible)acc.push(n.characters);if("children" in n)n.children.forEach(c=>{if(c.visible)texts(c,acc)});return acc;}
const out={};
for(const nm of ["04_Home","07_Profile","05_My_Asset_Overlay"]){
